/**
 * 工作流配方解析与校验（架构 §11.2）。
 * 定义文件：`<PAO_HOME>/工作流/<名字>.md`（YAML frontmatter + 正文说明），类 skill 可复制可改可分享。
 * 工作流是配方不是任务状态：本模块只做加载/校验/参数代入，运行时真相仍在卡上（§11 定位）。
 * 校验照架构定案：有向无环（自依赖/成环/引用不存在节点一律拒绝加载）；参数占位符启动时必须全部有值。
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

import { parseFrontmatter } from "../../utils/frontmatter.ts";
import { validateCardBudget } from "../cards/cardfile.ts";
import type { CardBudget, CardPriority, CardTier } from "../cards/types.ts";
import { CARD_PRIORITIES, CARD_TIERS } from "../cards/types.ts";

/** 工作流配方结构化错误：code 稳定可判，details 带机器可读上下文（与 PaoCardError 同口径）。 */
export type WorkflowRecipeErrorCode =
	| "RECIPE_NOT_FOUND" // 配方文件不存在
	| "RECIPE_PARSE" // frontmatter 不是合法 YAML 映射
	| "RECIPE_FIELD" // 缺必需字段 / 字段非法
	| "RECIPE_DEP_UNKNOWN" // depends_on 引用了节点表里不存在的节点（未知卡）
	| "RECIPE_DEP_SELF" // 节点依赖自身
	| "RECIPE_CYCLE" // 依赖图成环
	| "RECIPE_PARAM_PLACEHOLDER" // 模板里出现未声明的参数占位符
	| "RECIPE_PARAM_MISSING"; // 启动时声明的参数占位符没有拿到值

export class WorkflowRecipeError extends Error {
	readonly code: WorkflowRecipeErrorCode;
	readonly details: Record<string, unknown>;

	constructor(code: WorkflowRecipeErrorCode, message: string, details: Record<string, unknown> = {}) {
		super(message);
		this.name = "WorkflowRecipeError";
		this.code = code;
		this.details = details;
	}
}

export function isWorkflowRecipeError(error: unknown): error is WorkflowRecipeError {
	return error instanceof WorkflowRecipeError;
}

/** 节点＝卡模板字段 + depends_on + 人工确认标记（§11.1：格子给方向，部门配方给干法）。 */
export interface RecipeNode {
	名字: string;
	/** 卡模板字段（原样带占位符，启动时代入参数） */
	目标: string;
	部门: string;
	验收: string;
	输入?: string[];
	约束?: string;
	档位?: CardTier;
	预算?: CardBudget;
	优先级?: CardPriority;
	/**
	 * 按需技能（§11.6）：名字对应 <PAO_HOME>/pao配置/skills/ 下条目——平常不挂载,
	 * 派到本节点卡时由派发收口层（resolveDispatchParameters）自动挂载;缺文件拒派（fail-closed）。
	 */
	技能?: string[];
	depends_on: string[];
	/** 人工确认标记：交付后停流等用户点头才放行下游（§11.1 决定 2） */
	人工确认: boolean;
}

export interface WorkflowRecipe {
	名字: string;
	适用?: string;
	/**
	 * 自动执行链（M2-06）：true 时 启流/推流/确认流 走 workflow/auto.ts——
	 * 落卡后自动 派发→回执→越界核查→机械验收→交卷→解锁下游；缺省 false＝手动链不变。
	 */
	自动执行: boolean;
	/** 声明的参数名列表 */
	参数: string[];
	节点: RecipeNode[];
	/** 正文说明（给人读的使用说明，不参与机械执行） */
	说明: string;
	/** 配方文件绝对路径 */
	文件路径: string;
	/** 模板字段里实际出现的占位符（去重保序） */
	占位符: string[];
	/** 拓扑序的节点名字（加载时算好，驱动器直接用） */
	拓扑序: string[];
}

const PLACEHOLDER_PATTERN = /\{([^{}\s]+)\}/g;

/** 收集字符串（或字符串数组）里的参数占位符，去重保序。 */
function collectPlaceholders(value: string | string[] | undefined): string[] {
	const out: string[] = [];
	const scan = (text: string) => {
		for (const match of text.matchAll(PLACEHOLDER_PATTERN)) {
			if (!out.includes(match[1])) out.push(match[1]);
		}
	};
	if (typeof value === "string") scan(value);
	if (Array.isArray(value)) for (const item of value) scan(item);
	return out;
}

/** 参数代入：只替换已声明且有值的占位符，其余原样保留（加载时已校验不存在未声明占位符）。 */
export function substituteParams(template: string, params: Record<string, string>): string {
	return template.replace(PLACEHOLDER_PATTERN, (whole, name: string) => params[name] ?? whole);
}

/** $PAO_HOME/工作流/<名字>.md 的落点。paoHome 由调用方解析传入（测试注入 fixture 目录），不硬编码。 */
export function recipePath(paoHome: string, 名字: string): string {
	return join(paoHome, "工作流", `${名字}.md`);
}

/** 列出可用配方名字（文件名去 .md，按名字排序）。目录不存在视为空。 */
export function listRecipes(paoHome: string): string[] {
	const dir = join(paoHome, "工作流");
	if (!existsSync(dir)) return [];
	return readdirSync(dir)
		.filter((name) => name.endsWith(".md"))
		.map((name) => name.slice(0, -3))
		.sort();
}

/**
 * 配方名口径（与 saveRecipe 落盘校验同款、与卡标记解析兼容）：非空、≤64、无空白、
 * 无路径分隔符/Windows 非法字符、不是点名字。带空格的流名写得出、读不回（标记正则拒空白），
 * 路径分隔符可穿越到工作流目录之外，一律在加载/保存/启动前拒绝。
 */
export function 校验配方名(名字: string): void {
	if (typeof 名字 !== "string" || 名字 === "") {
		throw new WorkflowRecipeError("RECIPE_FIELD", "配方名不能为空", { 名字 });
	}
	if (名字.trim() !== 名字) {
		throw new WorkflowRecipeError("RECIPE_FIELD", `配方名不能带首尾空白：${JSON.stringify(名字)}`, { 名字 });
	}
	if (/\s/.test(名字)) {
		throw new WorkflowRecipeError(
			"RECIPE_FIELD",
			`配方名不能含空白（带空格的流名写得出、读不回）：${JSON.stringify(名字)}`,
			{
				名字,
			},
		);
	}
	if (名字.length > 64) {
		throw new WorkflowRecipeError("RECIPE_FIELD", `配方名过长（≤64）：${名字}`, { 名字 });
	}
	if (/[\\/:*?"<>|]/.test(名字) || 名字 === "." || 名字 === "..") {
		throw new WorkflowRecipeError("RECIPE_FIELD", `配方名含非法字符（路径分隔符/:*?"<>|\\）或为点名字：${名字}`, {
			名字,
		});
	}
}

function requireString(
	raw: Record<string, unknown>,
	key: string,
	where: string,
	problems: string[],
): string | undefined {
	const value = raw[key];
	if (typeof value !== "string" || value.trim() === "") {
		problems.push(`${where} 缺必需字段「${key}」（须为非空字符串）`);
		return undefined;
	}
	return value;
}

function optionalStringArray(
	raw: Record<string, unknown>,
	key: string,
	where: string,
	problems: string[],
): string[] | undefined {
	const value = raw[key];
	if (value === undefined) return undefined;
	if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
		problems.push(`${where} 字段「${key}」须为字符串数组`);
		return undefined;
	}
	return value as string[];
}

/**
 * 解析配方文件内容（字符串）为 WorkflowRecipe，做全量加载校验。
 * 校验失败抛 WorkflowRecipeError；字段类问题尽量一次列全（details.problems）。
 */
export function parseRecipe(content: string, filePath: string): WorkflowRecipe {
	let frontmatter: Record<string, unknown>;
	let 说明: string;
	try {
		const parsed = parseFrontmatter<Record<string, unknown>>(content);
		frontmatter = parsed.frontmatter;
		说明 = parsed.body;
	} catch (error) {
		throw new WorkflowRecipeError("RECIPE_PARSE", `配方 frontmatter 不是合法 YAML：${filePath}（${String(error)}）`, {
			filePath,
			cause: String(error),
		});
	}
	if (typeof frontmatter !== "object" || frontmatter === null || Array.isArray(frontmatter)) {
		throw new WorkflowRecipeError("RECIPE_PARSE", `配方 frontmatter 缺失或不是映射：${filePath}`, { filePath });
	}

	const problems: string[] = [];
	const 名字 = requireString(frontmatter, "名字", "配方", problems);
	if (名字 !== undefined) {
		try {
			校验配方名(名字);
		} catch (error) {
			problems.push(error instanceof Error ? error.message : String(error));
		}
		const stem = filePath.split(/[\\/]/).pop()?.replace(/\.md$/, "");
		if (stem !== 名字) {
			problems.push(`配方「名字」（${名字}）与文件名（${stem}.md）不一致，改名须同步改文件名`);
		}
	}
	const 适用 = typeof frontmatter.适用 === "string" ? frontmatter.适用 : undefined;
	const 自动执行 = frontmatter.自动执行;
	if (自动执行 !== undefined && typeof 自动执行 !== "boolean") {
		problems.push("配方字段「自动执行」须为布尔值（true=派发→验收→交卷全自动链；缺省 false 手动）");
	}
	const 参数 = optionalStringArray(frontmatter, "参数", "配方", problems) ?? [];

	const rawNodes = frontmatter.节点;
	if (!Array.isArray(rawNodes) || rawNodes.length === 0) {
		problems.push("配方缺「节点」表（须为非空数组）");
	}
	const 节点: RecipeNode[] = [];
	const seen = new Set<string>();
	for (const [index, rawNode] of Array.isArray(rawNodes) ? rawNodes.entries() : []) {
		const where = `节点[${index}]`;
		if (typeof rawNode !== "object" || rawNode === null) {
			problems.push(`${where} 须为映射`);
			continue;
		}
		const node = rawNode as Record<string, unknown>;
		const 节点名字 = requireString(node, "名字", where, problems);
		const 目标 = requireString(node, "目标", where, problems);
		const 部门 = requireString(node, "部门", where, problems);
		const 验收 = requireString(node, "验收", where, problems);
		if (节点名字 !== undefined) {
			if (seen.has(节点名字)) problems.push(`${where} 名字「${节点名字}」重复`);
			seen.add(节点名字);
		}
		const 输入 = optionalStringArray(node, "输入", where, problems);
		const 技能 = optionalStringArray(node, "技能", where, problems);
		const depends_on = optionalStringArray(node, "depends_on", where, problems) ?? [];
		const 人工确认 = node.人工确认;
		if (人工确认 !== undefined && typeof 人工确认 !== "boolean") {
			problems.push(`${where} 字段「人工确认」须为布尔值`);
		}
		const 档位 = node.档位;
		if (档位 !== undefined && !CARD_TIERS.includes(档位 as CardTier)) {
			problems.push(`${where} 档位非法：${String(档位)}（可选 ${CARD_TIERS.join("/")}）`);
		}
		const 优先级 = node.优先级;
		let 预算: CardBudget | undefined;
		try {
			预算 = validateCardBudget(node.预算);
		} catch (error) {
			problems.push(`${where} ${error instanceof Error ? error.message : String(error)}`);
		}
		if (优先级 !== undefined && !CARD_PRIORITIES.includes(优先级 as CardPriority)) {
			problems.push(`${where} 优先级非法：${String(优先级)}（可选 ${CARD_PRIORITIES.join("/")}）`);
		}
		if (节点名字 === undefined || 目标 === undefined || 部门 === undefined || 验收 === undefined) continue;
		节点.push({
			名字: 节点名字,
			目标,
			部门,
			验收,
			输入,
			约束: typeof node.约束 === "string" ? node.约束 : undefined,
			档位: 档位 as CardTier | undefined,
			预算,
			优先级: 优先级 as CardPriority | undefined,
			技能,
			depends_on,
			人工确认: 人工确认 === true,
		});
	}
	if (problems.length > 0) {
		throw new WorkflowRecipeError(
			"RECIPE_FIELD",
			`配方字段校验失败（${problems.length} 处）：${filePath}；${problems.join("；")}`,
			{
				filePath,
				problems,
			},
		);
	}

	// 依赖引用校验：未知节点（未知卡）与自依赖
	for (const node of 节点) {
		for (const dep of node.depends_on) {
			if (dep === node.名字) {
				throw new WorkflowRecipeError("RECIPE_DEP_SELF", `节点「${node.名字}」依赖自身`, {
					filePath,
					节点: node.名字,
				});
			}
			if (!seen.has(dep)) {
				throw new WorkflowRecipeError(
					"RECIPE_DEP_UNKNOWN",
					`节点「${node.名字}」depends_on 引用了节点表里不存在的「${dep}」`,
					{
						filePath,
						节点: node.名字,
						引用: dep,
					},
				);
			}
		}
	}

	// 环检查（Kahn 拓扑）：删不完 = 成环，拒绝加载（§11.2 只认有向无环）
	const 入度 = new Map<string, number>(节点.map((node) => [node.名字, 0]));
	const 下游 = new Map<string, string[]>(节点.map((node) => [node.名字, []]));
	for (const node of 节点) {
		for (const dep of node.depends_on) {
			入度.set(node.名字, (入度.get(node.名字) ?? 0) + 1);
			下游.get(dep)!.push(node.名字);
		}
	}
	const 拓扑序: string[] = [];
	const queue = 节点.filter((node) => 入度.get(node.名字) === 0).map((node) => node.名字);
	while (queue.length > 0) {
		const current = queue.shift()!;
		拓扑序.push(current);
		for (const next of 下游.get(current)!) {
			const remaining = (入度.get(next) ?? 0) - 1;
			入度.set(next, remaining);
			if (remaining === 0) queue.push(next);
		}
	}
	if (拓扑序.length !== 节点.length) {
		const 成环节点 = 节点.filter((node) => 入度.get(node.名字)! > 0).map((node) => node.名字);
		throw new WorkflowRecipeError("RECIPE_CYCLE", `工作流依赖成环，拒绝加载：${成环节点.join(" → ")}`, {
			filePath,
			成环节点,
		});
	}

	// 占位符必须全部已声明：启动时代入才有依据
	const 出现的占位符: string[] = [];
	const scanNode = (node: RecipeNode) => {
		for (const found of collectPlaceholders(node.目标)) if (!出现的占位符.includes(found)) 出现的占位符.push(found);
		for (const found of collectPlaceholders(node.验收)) if (!出现的占位符.includes(found)) 出现的占位符.push(found);
		if (node.约束)
			for (const found of collectPlaceholders(node.约束))
				if (!出现的占位符.includes(found)) 出现的占位符.push(found);
		if (node.输入)
			for (const item of node.输入)
				for (const found of collectPlaceholders(item)) if (!出现的占位符.includes(found)) 出现的占位符.push(found);
	};
	for (const node of 节点) scanNode(node);
	const 未声明 = 出现的占位符.filter((name) => !参数.includes(name));
	if (未声明.length > 0) {
		throw new WorkflowRecipeError(
			"RECIPE_PARAM_PLACEHOLDER",
			`配方模板出现未声明的参数占位符：${未声明.join("、")}（请在 frontmatter「参数」里声明）`,
			{ filePath, 未声明, 已声明: 参数 },
		);
	}

	return {
		名字: 名字!,
		适用,
		自动执行: 自动执行 === true,
		参数,
		节点,
		说明,
		文件路径: filePath,
		占位符: 出现的占位符,
		拓扑序,
	};
}

/** 读配方文件并解析校验。名字非法抛 RECIPE_FIELD（先于拼路径，杜绝穿越），不存在抛 RECIPE_NOT_FOUND，内容坏抛对应结构化错误。 */
export function loadRecipe(paoHome: string, 名字: string): WorkflowRecipe {
	校验配方名(名字);
	const path = recipePath(paoHome, 名字);
	if (!existsSync(path)) {
		const available = listRecipes(paoHome);
		throw new WorkflowRecipeError(
			"RECIPE_NOT_FOUND",
			`找不到工作流配方：${path}${available.length > 0 ? `（可用：${available.join("、")}）` : "（工作流目录为空或不存在）"}`,
			{ paoHome, 名字, path, 可用: available },
		);
	}
	return parseRecipe(readFileSync(path, "utf8"), path);
}

/** 启动前参数校验：声明的占位符必须全部有值（§11.2），多给的参数忽略。缺值抛 RECIPE_PARAM_MISSING。 */
export function requireParams(recipe: WorkflowRecipe, params: Record<string, string>): void {
	const missing = recipe.占位符.filter((name) => params[name] === undefined || params[name] === "");
	if (missing.length > 0) {
		throw new WorkflowRecipeError(
			"RECIPE_PARAM_MISSING",
			`工作流「${recipe.名字}」的参数占位符缺值：${missing.join("、")}`,
			{ 工作流: recipe.名字, 缺: missing, 已提供: Object.keys(params) },
		);
	}
}

/**
 * 工作流配方蒸馏与落盘（2026-10-03 拍板「走完一次存配方」的机械半边）。
 *
 * - distillRecipe：扫卡目录→配方草稿（**逐字**提取——目标/部门/验收/约束/输入/档位/预算/优先级
 *   原样进节点，依赖卡号映射为节点名；人工确认一律 false：手动跑的任务没有确认留痕，
 *   审草稿时人工标）。草稿必须过 parseRecipe 全量校验（依赖成环拒绝出稿）才返回，**不落盘**——
 *   参数化建议（项目名/路径换 {参数} 占位符）留给主控/用户审时定，机械层不猜。
 * - saveRecipe：内容过 parseRecipe 全量校验（frontmatter 可解析、文件名与「名字」一致、
 *   依赖无环、占位符全部已声明）才原子写 `<PAO_HOME>/工作流/<名字>.md`；同名默认拒绝，
 *   显式覆盖先备份 `.bak-时间戳`（与 档位.json 编辑器同款纪律）。蒸馏路与对话起草路共用此闸。
 *
 * 纯函数纪律：不取当前时钟——蒸馏时间/备份时间由调用方传入（工具层取，测试注入）。
 */
import { copyFileSync, existsSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";

import { writeFileAtomic } from "../cards/atomic.ts";
import { readCard } from "../cards/cardfile.ts";
import { parseCardRef } from "../cards/counter.ts";
import type { CardBudget, CardPriority, CardTier, ParsedCard } from "../cards/types.ts";
import { parseRecipe, recipePath, WorkflowRecipeError } from "./recipe.ts";

/** 蒸馏节点＝RecipeNode 的可发射形态（全部字段已从卡面定值,无占位符加工）。 */
interface DistilledNode {
	名字: string;
	目标: string;
	部门: string;
	验收: string;
	输入?: string[];
	约束?: string;
	档位?: CardTier;
	预算?: CardBudget;
	优先级?: CardPriority;
	depends_on: string[];
	人工确认: boolean;
}

export interface DistillResult {
	/** 完整配方 markdown（frontmatter＋说明正文）,已过 parseRecipe 校验 */
	content: string;
	卡数: number;
	边数: number;
	/** 非卡文件与坏卡（原样点名,不静默丢弃） */
	跳过: string[];
}

/** YAML 双引号标量:JSON 字符串是合法 YAML（yaml 包按 YAML 1.2 双引风格解析,转义同源）。 */
function yamlString(value: string): string {
	return JSON.stringify(value);
}

function yamlStringArray(values: string[]): string {
	return `[${values.map(yamlString).join(", ")}]`;
}

/** 配方 markdown 发射器（字段顺序与手工配方一致;串一律双引号,数组/预算用 flow 风格）。 */
export function emitRecipeMarkdown(input: {
	名字: string;
	自动执行: boolean;
	参数: string[];
	节点: DistilledNode[];
	说明: string;
}): string {
	const lines: string[] = ["---"];
	lines.push(`名字: ${yamlString(input.名字)}`);
	lines.push(`自动执行: ${input.自动执行}`);
	lines.push(`参数: ${yamlStringArray(input.参数)}`);
	lines.push("节点:");
	for (const node of input.节点) {
		lines.push(`  - 名字: ${yamlString(node.名字)}`);
		lines.push(`    目标: ${yamlString(node.目标)}`);
		lines.push(`    部门: ${yamlString(node.部门)}`);
		lines.push(`    验收: ${yamlString(node.验收)}`);
		if (node.输入) lines.push(`    输入: ${yamlStringArray(node.输入)}`);
		if (node.约束) lines.push(`    约束: ${yamlString(node.约束)}`);
		if (node.档位) lines.push(`    档位: ${node.档位}`);
		if (node.预算) lines.push(`    预算: ${JSON.stringify(node.预算)}`);
		if (node.优先级) lines.push(`    优先级: ${node.优先级}`);
		lines.push(`    depends_on: ${yamlStringArray(node.depends_on)}`);
		lines.push(`    人工确认: ${node.人工确认}`);
	}
	lines.push("---");
	lines.push(input.说明);
	return `${lines.join("\n")}\n`;
}

/** 卡文件名 → 节点名：去「卡NNNN-」前缀取 slug;空 slug 或撞名时退回含卡号全名保唯一。 */
function nodeName(卡: ParsedCard, taken: Set<string>): string {
	const stem = 卡.文件名.replace(/\.md$/, "");
	const slug = stem.replace(/^卡0*\d+-/, "");
	const candidate = slug.length > 0 ? slug : `节点${卡.卡号}`;
	return taken.has(candidate) ? stem : candidate;
}

function formatMtime(ms: number): string {
	const d = new Date(ms);
	const pad = (n: number) => String(n).padStart(2, "0");
	return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

/**
 * 任务窗（最早创建~最晚完成,均 YYYY-MM-DD HH:mm 字符串比较）内部门知识库新增条目点名。
 * mtime 口径:机械可查、不依赖入库是否记时间字段;没有完成时间时窗只设下界。
 */
function collectDeptKnowledge(paoHome: string, cards: ParsedCard[]): string[] {
	const 创建 = cards.map((c) => c.frontmatter.创建).filter((v): v is string => typeof v === "string");
	if (创建.length === 0) return [];
	const lower = 创建.reduce((a, b) => (a < b ? a : b));
	const 完成 = cards.map((c) => c.frontmatter.完成).filter((v): v is string => typeof v === "string");
	const upper = 完成.length > 0 ? 完成.reduce((a, b) => (a > b ? a : b)) : undefined;
	const hits: string[] = [];
	for (const 部门 of new Set(cards.map((c) => c.frontmatter.部门).filter(Boolean))) {
		const root = join(paoHome, "部门", 部门, "知识库");
		if (!existsSync(root)) continue;
		const walk = (dir: string) => {
			for (const entry of readdirSync(dir, { withFileTypes: true })) {
				const path = join(dir, entry.name);
				if (entry.isDirectory()) walk(path);
				else if (entry.name.endsWith(".md")) {
					const mtime = formatMtime(statSync(path).mtimeMs);
					if (mtime >= lower && (upper === undefined || mtime <= upper))
						hits.push(`${部门}/知识库/${relative(root, path).split(/[\\/]/).join("/")}`);
				}
			}
		};
		walk(root);
	}
	return hits;
}

/**
 * 蒸馏卡目录为配方草稿。依赖引用指向本目录外的卡（卡号查无）→ 拒绝出稿；
 * 蒸馏出的依赖图成环 → parseRecipe 抛 RECIPE_CYCLE。空目录/无有效卡 → 抛错。
 *
 * 蒸馏增强（§11.6,2026-10-03 拍板「提取时也要提取部门、工人里面的工作流程」）:
 * - 卡树:frontmatter.parent（协作母卡）也映射为依赖边（与 depends_on 合并去重）;
 * - 实施记录:每卡末次成功回执的摘要＋产物路径进说明正文,重跑照抄有据;
 * - 部门经验:给了 paoHome 时,任务时间窗内（最早创建~最晚完成,mtime 口径）部门知识库
 *   新增条目点名进说明正文——点名不搬内容,细节仍查知识库本体。
 */
export function distillRecipe(cardsDir: string, 配方名: string, 蒸馏时间: string, paoHome?: string): DistillResult {
	const entries = readdirSync(cardsDir); // 目录不存在直接抛 ENOENT（调用方转人话）
	const cardFiles = entries.filter((name) => /^卡0*\d+-.*\.md$/.test(name));
	const 跳过 = entries.filter((name) => !/^卡0*\d+-.*\.md$/.test(name));

	const cards: ParsedCard[] = [];
	for (const name of cardFiles) {
		try {
			cards.push(readCard(join(cardsDir, name)));
		} catch (error) {
			跳过.push(`${name}（坏卡:${error instanceof Error ? error.message : String(error)}）`);
		}
	}
	if (cards.length === 0) {
		throw new WorkflowRecipeError(
			"RECIPE_FIELD",
			`卡目录没有可蒸馏的有效卡：${cardsDir}${跳过.length > 0 ? `（${跳过.length} 个非卡/坏文件已点名）` : ""}`,
			{ cardsDir, 跳过 },
		);
	}

	const taken = new Set<string>();
	const nameByCard = new Map<number, string>();
	for (const card of cards) {
		const name = nodeName(card, taken);
		taken.add(name);
		nameByCard.set(card.卡号, name);
	}

	const nodes: DistilledNode[] = [];
	let 边数 = 0;
	for (const card of cards) {
		const depends_on: string[] = [];
		for (const ref of card.frontmatter.depends_on ?? []) {
			// 手编卡常见裸数字依赖,YAML 往返后是 number 不是 string——先归一再解析
			const refText = String(ref);
			const 卡号 = parseCardRef(refText); // 引用形态非法（非卡号）→ PaoCardError 原样上抛
			const mapped = nameByCard.get(卡号);
			if (mapped === undefined) {
				throw new WorkflowRecipeError(
					"RECIPE_DEP_UNKNOWN",
					`卡「${card.文件名}」的依赖「${refText}」不在本卡目录（蒸馏只收目录内卡链,外部依赖先清掉再蒸馏）`,
					{ cardsDir, 卡: card.文件名, 引用: refText },
				);
			}
			if (!depends_on.includes(mapped)) depends_on.push(mapped);
		}
		// 卡树边（§11.6 蒸馏增强）:parent＝协作母卡,协作关系也是依赖关系——同一映射、同一拒绝口径
		if (card.frontmatter.parent) {
			const parentRef = String(card.frontmatter.parent);
			const 母卡号 = parseCardRef(parentRef);
			const mapped = nameByCard.get(母卡号);
			if (mapped === undefined) {
				throw new WorkflowRecipeError(
					"RECIPE_DEP_UNKNOWN",
					`卡「${card.文件名}」的 parent「${parentRef}」不在本卡目录（蒸馏只收目录内卡链,外部协作先清掉再蒸馏）`,
					{ cardsDir, 卡: card.文件名, 引用: parentRef },
				);
			}
			if (!depends_on.includes(mapped)) depends_on.push(mapped);
		}
		边数 += depends_on.length;
		const f = card.frontmatter;
		nodes.push({
			名字: nameByCard.get(card.卡号)!,
			目标: f.目标,
			部门: f.部门,
			验收: f.验收,
			输入: f.输入,
			约束: f.约束,
			档位: f.档位,
			预算: f.预算,
			优先级: f.优先级,
			depends_on,
			人工确认: false,
		});
	}

	// 实施记录（§11.6 蒸馏增强）:每卡末次成功回执的摘要＋产物——工人实际怎么干的留痕
	const cardByNode = new Map(
		nodes.map((node) => [node.名字, cards.find((c) => nameByCard.get(c.卡号) === node.名字)!]),
	);
	const 实施记录: string[] = [];
	for (const node of nodes) {
		const card = cardByNode.get(node.名字);
		const last = card ? [...card.回执].reverse().find((r) => r.结果 === "成功" && !r.留档标记) : undefined;
		if (!last) continue;
		const 产物 = last.产物路径?.length ? `（产物:${last.产物路径.join("、")}）` : "";
		实施记录.push(`- ${node.名字}:${last.摘要 ?? "（无摘要）"}${产物}`);
	}
	// 部门经验（§11.6 蒸馏增强）:任务窗内部门知识库新增条目点名（要 paoHome）
	const 部门经验 = paoHome ? collectDeptKnowledge(paoHome, cards) : [];

	const 说明 = [
		"## 蒸馏说明",
		"",
		`- 来源：卡目录 ${cardsDir}（${cards.length} 张卡、${边数} 条依赖边）,蒸馏时间 ${蒸馏时间}。`,
		"- 本草稿为逐字提取（未参数化）：审时建议把项目名/路径等可变处换成 `{参数}` 占位符,并在 frontmatter「参数」表声明。",
		"- 「人工确认」未检测（手动跑的任务没有确认留痕）,全部默认 false——审时按实际人工点头处标 true。",
		"- 自动执行缺省 false：确认手动链无误后,如需全链自动（派发→验收→交卷）再改 true。",
		"",
		"## 实施记录（蒸馏自末次成功回执,重跑可照抄）",
		"",
		...(实施记录.length > 0 ? 实施记录 : ["- （无成功回执——手动任务未留回执或全失败）"]),
		...(paoHome
			? [
					"",
					"## 部门经验（任务窗内知识库新增条目点名,mtime 口径）",
					"",
					...(部门经验.length > 0
						? 部门经验.map((entry) => `- ${entry}`)
						: ["- （窗内无新增——无对应部门知识库目录或条目都在窗外）"]),
				]
			: []),
		"",
		"## 使用说明",
		"",
		"（蒸馏草稿:描述这个工作流适合什么场景、怎么起参数）",
	].join("\n");

	const content = emitRecipeMarkdown({ 名字: 配方名, 自动执行: false, 参数: [], 节点: nodes, 说明 });
	// 发射即校验（roundtrip）：环/字段问题在这里拦下,不把坏草稿交给审的人。
	parseRecipe(content, join("工作流", `${配方名}.md`));
	return { content, 卡数: cards.length, 边数, 跳过 };
}

/** 配方文件名安全：非空、≤64、无路径分隔符/Windows 非法字符、不是点名字。 */
export function validateRecipeName(名字: string): void {
	const trimmed = 名字.trim();
	if (trimmed === "" || trimmed !== 名字) throw new Error(`配方名不能为空或带首尾空白：${JSON.stringify(名字)}`);
	if (名字.length > 64) throw new Error(`配方名过长（≤64）:${名字}`);
	if (/[\\/:*?"<>|]/.test(名字) || 名字 === "." || 名字 === "..") {
		throw new Error(`配方名含非法字符（路径分隔符/:*?"<>|）或为点名字：${名字}`);
	}
}

export interface SaveRecipeResult {
	路径: string;
	/** 覆盖时的旧文件备份路径 */
	备份?: string;
	节点数: number;
}

/**
 * 校验并落盘配方。校验＝parseRecipe 全量（含文件名与「名字」一致、无环、占位符声明一致）;
 * 原子写;同名默认拒绝,覆盖时先备份（备份时间由调用方传入,保持本函数可测）。
 */
export function saveRecipe(
	paoHome: string,
	名字: string,
	内容: string,
	options: { 覆盖?: boolean; 备份时间: string },
): SaveRecipeResult {
	validateRecipeName(名字);
	const path = recipePath(paoHome, 名字);
	const recipe = parseRecipe(内容, path); // 校验不过即抛,目录与文件零改动
	let 备份: string | undefined;
	if (existsSync(path)) {
		if (!options.覆盖) {
			throw new Error(`配方已存在:${path}（要覆盖旧版请显式传 覆盖:true,旧文件会先备份 .bak-时间戳）`);
		}
		备份 = `${path}.bak-${options.备份时间}`;
		copyFileSync(path, 备份);
	}
	mkdirSync(join(paoHome, "工作流"), { recursive: true });
	writeFileAtomic(path, 内容);
	return { 路径: path, 备份, 节点数: recipe.节点.length };
}

/**
 * 工作流复盘机械报告（§11.6 跑后复盘闭环,2026-10-03 用户拍板「每次跑完要检查本次实施,给我改进意见」）。
 *
 * 复盘是流程不是新状态:全部数据从既有账面（卡/回执/实例清单）现读,不建第二套真相（R10）。
 * 本模块只做机械汇总——每节点 派发次数/重试/打回/失败类型/末次摘要/产物/人工门/预算 vs 实耗;
 * 语义改进意见由主控基于报告给,用户拍板后经 pao_落配方 回写配方。本模块不调模型、不给建议。
 */

import { listCards } from "../cards/index.ts";
import type { CardStatus, ParsedCard } from "../cards/types.ts";
import { parseWorkflowMarker, type WorkflowManifest } from "./driver.ts";
import type { WorkflowRecipe } from "./recipe.ts";

export const WORKFLOW_REVIEW_SECTION = "pao-workflow-review";

export interface ReviewNodeRow {
	节点: string;
	卡号?: number;
	/** 卡现读状态（未落卡节点无卡） */
	卡状态?: CardStatus;
	/** 卡面尝试数 */
	尝试: number;
	/** 有效回执数（留档不算） */
	派发次数: number;
	/** 结果=失败 的回执数（含失败类型末次值） */
	打回: number;
	末次失败类型?: string;
	/** 配方人工门标记与实例清单点头时间 */
	人工确认: boolean;
	已确认?: string;
	末次成功摘要?: string;
	产物: string[];
	预算?: { turns?: number; toolCalls?: number; cost?: number };
	实耗: { turns: number; toolCalls: number; cost: number; 未知: boolean };
}

export interface ReviewReport {
	工作流: string;
	/** 实例清单状态（清单缺时 undefined,如实呈现） */
	实例状态?: WorkflowManifest["状态"];
	启动?: string;
	节点: ReviewNodeRow[];
	/** 标记指向配方已删节点的卡（孤儿,报告点名不丢弃） */
	孤儿卡: { 卡号: number; 节点: string; 卡状态: CardStatus }[];
}

/** 单卡回执用量聚合:跳过「汇总」行（母卡汇总=子卡之和,重复计）;缺项标未知不填零（R07）。 */
function sumUsage(cards: ParsedCard[]): { turns: number; toolCalls: number; cost: number; 未知: boolean } {
	const total = { turns: 0, toolCalls: 0, cost: 0, 未知: false };
	for (const card of cards) {
		for (const receipt of card.回执) {
			const usage = receipt.用量;
			if (!usage || usage.来源 === "汇总") continue;
			for (const key of ["turns", "toolCalls", "cost"] as const) {
				const value = usage[key];
				if (typeof value === "number" && Number.isFinite(value) && value >= 0) total[key] += value;
				else total.未知 = true;
			}
		}
	}
	return total;
}

/**
 * 从卡与实例清单现读构建复盘报告。节点行序＝配方拓扑序（没跑的节点也列出,尝试 0 如实）;
 * 卡面标记不在配方节点表里的进孤儿卡（配方改版后的旧卡,点名不静默）。
 */
export function buildReviewReport(recipe: WorkflowRecipe, cardsDir: string, manifest?: WorkflowManifest): ReviewReport {
	const cards = listCards(cardsDir);
	const cardByNode = new Map<string, ParsedCard>();
	const 孤儿卡: ReviewReport["孤儿卡"] = [];
	for (const card of cards) {
		const marker = parseWorkflowMarker(card.正文);
		if (!marker || marker.流 !== recipe.名字) continue;
		if (recipe.节点.some((node) => node.名字 === marker.节点)) cardByNode.set(marker.节点, card);
		else 孤儿卡.push({ 卡号: card.卡号, 节点: marker.节点, 卡状态: card.frontmatter.状态 });
	}

	const manifestByNode = new Map((manifest?.节点 ?? []).map((entry) => [entry.名字, entry]));
	const 节点: ReviewNodeRow[] = recipe.拓扑序.map((name) => {
		const node = recipe.节点.find((candidate) => candidate.名字 === name)!;
		const card = cardByNode.get(name);
		const entry = manifestByNode.get(name);
		if (!card) {
			return {
				节点: name,
				尝试: 0,
				派发次数: 0,
				打回: 0,
				人工确认: node.人工确认,
				已确认: entry?.确认,
				产物: [],
				实耗: { turns: 0, toolCalls: 0, cost: 0, 未知: false },
			};
		}
		const 有效回执 = card.回执.filter((receipt) => !receipt.留档标记);
		const 失败回执 = 有效回执.filter((receipt) => receipt.结果 === "失败");
		const 末次成功 = [...有效回执].reverse().find((receipt) => receipt.结果 === "成功");
		const 产物 = [
			...new Set(
				card.回执.filter((receipt) => receipt.结果 === "成功").flatMap((receipt) => receipt.产物路径 ?? []),
			),
		];
		return {
			节点: name,
			卡号: card.卡号,
			卡状态: card.frontmatter.状态,
			尝试: card.frontmatter.尝试,
			派发次数: 有效回执.length,
			打回: 失败回执.length,
			末次失败类型: 失败回执.at(-1)?.失败类型,
			人工确认: node.人工确认,
			已确认: entry?.确认,
			末次成功摘要: 末次成功?.摘要,
			产物,
			预算: node.预算,
			实耗: sumUsage([card]),
		};
	});

	return { 工作流: recipe.名字, 实例状态: manifest?.状态, 启动: manifest?.启动, 节点, 孤儿卡 };
}

function budgetLine(row: ReviewNodeRow): string {
	if (!row.预算 && !row.实耗.未知 && row.实耗.turns === 0 && row.实耗.toolCalls === 0) return "";
	const 预算 = row.预算
		? `${row.预算.turns ?? "?"}轮/${row.预算.toolCalls ?? "?"}次${row.预算.cost !== undefined ? `/$${row.预算.cost}` : ""}`
		: "未设";
	const 实耗 = `${row.实耗.turns}轮/${row.实耗.toolCalls}次/$${row.实耗.cost.toFixed(2)}${row.实耗.未知 ? "（有缺账,已知下界）" : ""}`;
	return `\n  预算 vs 实耗:${预算} | ${实耗}`;
}

/** 报告渲染:一行一节点＋用量行,末尾总账与下一步指引（主控意见→用户拍板→pao_落配方）。 */
export function renderReviewReport(report: ReviewReport): string {
	const lines: string[] = [
		`工作流「${report.工作流}」复盘（机械报告）`,
		`实例状态:${report.实例状态 ?? "（清单缺失）"}${report.启动 ? `（启动 ${report.启动}）` : ""}`,
		"",
	];
	for (const row of report.节点) {
		const parts = [
			`━ ${row.节点}`,
			row.卡号 !== undefined ? `卡${String(row.卡号).padStart(4, "0")}` : "未落卡",
			row.卡状态 ?? "",
			`尝试${row.尝试}${row.尝试 > 1 ? `（重试${row.尝试 - 1}）` : ""}`,
			`派发${row.派发次数}`,
			row.打回 > 0 ? `打回${row.打回}${row.末次失败类型 ? `(${row.末次失败类型})` : ""}` : "",
			row.人工确认 ? `人工门${row.已确认 ? `已确认 ${row.已确认}` : "未确认"}` : "",
		].filter(Boolean);
		lines.push(parts.join(" | "));
		if (row.末次成功摘要) lines.push(`  末次成功摘要:${row.末次成功摘要.split("\n")[0]}`);
		if (row.产物.length > 0) lines.push(`  产物:${row.产物.join("、")}`);
		const budget = budgetLine(row);
		if (budget) lines.push(budget.trimStart());
	}
	const 总尝试 = report.节点.reduce((sum, row) => sum + row.尝试, 0);
	const 总派发 = report.节点.reduce((sum, row) => sum + row.派发次数, 0);
	const 总打回 = report.节点.reduce((sum, row) => sum + row.打回, 0);
	lines.push("", `总账:节点 ${report.节点.length}、尝试 ${总尝试}、派发 ${总派发}、打回 ${总打回}。`);
	if (report.孤儿卡.length > 0)
		lines.push(
			`孤儿卡（标记的节点不在配方里,配方改版遗留）:${report.孤儿卡.map((card) => `卡${card.卡号}→${card.节点}(${card.卡状态})`).join("、")}`,
		);
	lines.push(
		"",
		"下一步:基于此报告给改进意见（哪步预算虚设/哪步常打回/哪步可并跑/人工门放对没有）,用户逐条拍板后用 pao_落配方 回写配方。",
	);
	return lines.join("\n");
}

