/**
 * 工作流复盘机械报告单测（十八批,§11.6 跑后复盘闭环）:
 * 从卡与回执现读——尝试/派发/打回/末次失败类型/末次成功摘要/产物/人工门/预算vs实耗;
 * 拓扑序含未落卡节点、孤儿卡点名不静默、汇总回执不重复计、缺用量标未知不填零。
 * fixture 一律临时目录。
 */
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { cardFileName, serializeCard, serializeReceipt } from "../../src/pao/cards/cardfile.ts";
import type { CardFrontmatter } from "../../src/pao/cards/types.ts";
import { type WorkflowManifest, workflowMarker } from "../../src/pao/workflow/driver.ts";
import { parseRecipe } from "../../src/pao/workflow/recipe.ts";
import { buildReviewReport, renderReviewReport } from "../../src/pao/workflow/review.ts";

const tempDirs: string[] = [];
afterEach(() => {
	for (const dir of tempDirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});

function makeDir(): string {
	const dir = mkdtempSync(join(tmpdir(), "pao-flow-review-"));
	tempDirs.push(dir);
	return dir;
}

function writeCard(
	cardsDir: string,
	卡号: number,
	goal: string,
	frontmatter: Partial<CardFrontmatter> & Pick<CardFrontmatter, "目标" | "部门" | "验收">,
	body: string,
): void {
	writeFileSync(
		join(cardsDir, cardFileName(卡号, goal)),
		serializeCard({ 尝试: 0, 创建: "2026-10-03 10:00", 状态: "已交付", ...frontmatter }, body),
		"utf8",
	);
}

const RECIPE_TEXT = [
	"---",
	'名字: "复盘流"',
	"自动执行: false",
	"参数: []",
	"节点:",
	'  - 名字: "侦察"',
	'    目标: "扫仓库"',
	'    部门: "侦察"',
	'    验收: "包含: 扫"',
	'    预算: { "turns": 20, "toolCalls": 100 }',
	"    depends_on: []",
	"    人工确认: false",
	'  - 名字: "文档"',
	'    目标: "写文档"',
	'    部门: "文档"',
	'    验收: "包含: 文档"',
	'    depends_on: ["侦察"]',
	"    人工确认: true",
	'  - 名字: "未跑"',
	'    目标: "兜底"',
	'    部门: "前端"',
	'    验收: "包含: 兜"',
	'    depends_on: ["文档"]',
	"    人工确认: false",
	"---",
	"说明",
].join("\n");

function manifest(): WorkflowManifest {
	return {
		工作流: "复盘流",
		卡目录: "unused",
		启动: "2026-10-03 10:00",
		状态: "已完成",
		参数: {},
		节点: [
			{ 名字: "侦察", 卡号: "0001" },
			{ 名字: "文档", 卡号: "0002", 确认: "2026-10-03 11:30" },
		],
	};
}

describe("buildReviewReport / renderReviewReport", () => {
	it("每节点行:尝试重试/派发/打回失败类型/末次摘要/产物/人工门/预算vs实耗;未落卡如实列出", () => {
		const cardsDir = makeDir();
		writeCard(
			cardsDir,
			1,
			"侦察",
			{ 目标: "扫仓库", 部门: "侦察", 验收: "包含: 扫", 尝试: 2 },
			[
				workflowMarker("复盘流", "侦察"),
				serializeReceipt({
					卡号: 1,
					尝试号: 1,
					时间: "2026-10-03 10:20",
					结果: "失败",
					失败类型: "瞬时故障",
					摘要: "第一次挂了",
				}),
				serializeReceipt({
					卡号: 1,
					尝试号: 2,
					时间: "2026-10-03 10:40",
					结果: "成功",
					摘要: "产出了地图",
					产物路径: ["docs/地图.md"],
					用量: { turns: 8, toolCalls: 40, cost: 0.1 },
				}),
			].join("\n\n"),
		);
		writeCard(
			cardsDir,
			2,
			"文档",
			{ 目标: "写文档", 部门: "文档", 验收: "包含: 文档", 尝试: 1 },
			[
				workflowMarker("复盘流", "文档"),
				serializeReceipt({
					卡号: 2,
					尝试号: 1,
					时间: "2026-10-03 11:00",
					结果: "成功",
					摘要: "写完使用说明",
					产物路径: ["docs/使用.md"],
					用量: { 来源: "汇总", turns: 8, toolCalls: 40 }, // 汇总行不重复计
				}),
			].join("\n\n"),
		);
		const recipe = parseRecipe(RECIPE_TEXT, join("工作流", "复盘流.md"));
		const report = buildReviewReport(recipe, cardsDir, manifest());

		expect(report.实例状态).toBe("已完成");
		expect(report.节点.map((row) => row.节点)).toEqual(["侦察", "文档", "未跑"]);
		const 侦察 = report.节点[0];
		expect(侦察.尝试).toBe(2);
		expect(侦察.派发次数).toBe(2);
		expect(侦察.打回).toBe(1);
		expect(侦察.末次失败类型).toBe("瞬时故障");
		expect(侦察.末次成功摘要).toBe("产出了地图");
		expect(侦察.产物).toEqual(["docs/地图.md"]);
		expect(侦察.预算).toEqual({ turns: 20, toolCalls: 100 });
		expect(侦察.实耗).toEqual({ turns: 8, toolCalls: 40, cost: 0.1, 未知: false });
		const 文档 = report.节点[1];
		expect(文档.人工确认).toBe(true);
		expect(文档.已确认).toBe("2026-10-03 11:30");
		expect(文档.实耗).toEqual({ turns: 0, toolCalls: 0, cost: 0, 未知: false }); // 汇总行跳过
		const 未跑 = report.节点[2];
		expect(未跑.尝试).toBe(0);
		expect(未跑.产物).toEqual([]);

		const text = renderReviewReport(report);
		expect(text).toContain("复盘（机械报告）");
		expect(text).toContain("尝试2（重试1）");
		expect(text).toContain("打回1(瞬时故障)");
		expect(text).toContain("未落卡");
		expect(text).toContain("20轮/100次 | 8轮/40次/$0.10");
		expect(text).toContain("总账:节点 3、尝试 3、派发 3、打回 1");
		expect(text).toContain("pao_落配方");
	});

	it("孤儿卡（标记的节点不在配方）点名不静默;缺用量标未知不填零", () => {
		const cardsDir = makeDir();
		writeCard(
			cardsDir,
			5,
			"旧节点",
			{ 目标: "已被删", 部门: "前端", 验收: "包含: 删", 尝试: 1, 状态: "失败" },
			`${workflowMarker("复盘流", "已删节点")}\n\n${serializeReceipt({
				卡号: 5,
				尝试号: 1,
				时间: "2026-10-03 10:20",
				结果: "成功",
				用量: { turns: 3 }, // 缺 toolCalls/cost
			})}`,
		);
		const recipe = parseRecipe(RECIPE_TEXT, join("工作流", "复盘流.md"));
		const report = buildReviewReport(recipe, cardsDir, undefined);
		expect(report.孤儿卡).toEqual([{ 卡号: 5, 节点: "已删节点", 卡状态: "失败" }]);
		const text = renderReviewReport(report);
		expect(text).toContain("孤儿卡");
		expect(text).toContain("已删节点");
		expect(report.实例状态).toBeUndefined();
		expect(text).toContain("（清单缺失）");
		// 缺用量不填零:孤儿卡不进节点行（配方已删该节点）,其用量只在孤儿点名里呈现,不进总账
		expect(report.节点.every((row) => row.卡号 !== 5)).toBe(true);
	});

	it("别的流的卡不串台（marker 流名不匹配即忽略）", () => {
		const cardsDir = makeDir();
		writeCard(
			cardsDir,
			1,
			"外卡",
			{ 目标: "别家", 部门: "前端", 验收: "包含: 别", 尝试: 1 },
			`${workflowMarker("别的流", "侦察")}\n\n正文`,
		);
		const recipe = parseRecipe(RECIPE_TEXT, join("工作流", "复盘流.md"));
		const report = buildReviewReport(recipe, cardsDir, undefined);
		expect(report.节点.every((row) => row.卡号 === undefined)).toBe(true);
		expect(report.孤儿卡).toEqual([]);
	});
});

