interface NodeState {
	node: RecipeNode;
	entry: ManifestNodeEntry;
	卡?: ParsedCard;
	状态: CardStatus | "未落卡" | "读取异常";
	/** deps 全部完成（已交付且过人工门） */
	可落卡: boolean;
}

function evaluateStates(
	recipe: WorkflowRecipe,
	manifest: WorkflowManifest,
	options: DriverOptions,
): Map<string, NodeState> {
	const states = new Map<string, NodeState>();
	const byName = new Map(manifest.节点.map((entry) => [entry.名字, entry]));
	for (const name of recipe.拓扑序) {
		const node = recipe.节点.find((candidate) => candidate.名字 === name)!;
		const entry = byName.get(name) ?? { 名字: name };
		let 卡: ParsedCard | undefined;
		let 状态: CardStatus | "未落卡" | "读取异常" = "未落卡";
		if (entry.卡号 !== undefined) {
			try {
				卡 = loadCard(options.cardsDir, parseCardRef(entry.卡号));
				状态 = 卡.frontmatter.状态;
			} catch {
				状态 = "读取异常";
			}
		}
		const 完成 = (depName: string): boolean => {
			const dep = states.get(depName);
			if (!dep || dep.状态 !== "已交付") return false;
			const depNode = recipe.节点.find((candidate) => candidate.名字 === depName)!;
			return !depNode.人工确认 || dep.entry.确认 !== undefined;
		};
		states.set(name, {
			node,
			entry,
			卡,
			状态,
			可落卡: 状态 === "未落卡" && node.depends_on.every(完成),
		});
	}
	return states;
}

/** 人工门待点头的挂起文案（清单/报告/toast 判断共用一个口径，判人工门用结构化字段别再对文案）。 */
export const 人工门挂起原因 = "等待人工确认";

/**
 * 叫人去重键（§23 toast②）：同一门实例只弹一次 toast 的实例标识。
 * 结构化主判据＝报告里 挂起=人工门挂起原因 的节点（键 门:<节点>）；留 owner 无结构化信号，
 * 优先用卡在途节点（同一张卡是同一实例，键 owner:<节点>:<卡号>），没有再退化到停因文案。
 * 门换节点/换卡 → 键变 → 允许再叫；门被确认后再挂 → 记录已清（confirmWorkflowNode）→ 允许再叫。
 */
export function 挂起叫人键(report: DriveReport, 停因?: string): string | undefined {
	const 门 = report.节点.find((node) => node.挂起 === 人工门挂起原因);
	if (门) return `门:${门.名字}`;
	if (停因 === undefined || !停因.includes("留 owner")) return undefined;
	const 在途 = report.节点.find((node) => node.状态 === "进行中");
	return 在途 ? `owner:${在途.名字}:${在途.卡号 ?? ""}` : `owner:${停因}`;

import { parse } from "yaml";
import { stripBom } from "./text.ts";

type ParsedFrontmatter<T extends Record<string, unknown>> = {
	frontmatter: T;
	body: string;
};

const normalizeNewlines = (value: string): string => value.replace(/\r\n/g, "\n").replace(/\r/g, "\n");

const extractFrontmatter = (content: string): { yamlString: string | null; body: string } => {
	const normalized = normalizeNewlines(stripBom(content));

	if (!normalized.startsWith("---")) {
		return { yamlString: null, body: normalized };
	}

	const endIndex = normalized.indexOf("\n---", 3);
	if (endIndex === -1) {
		return { yamlString: null, body: normalized };
	}

	return {
		yamlString: normalized.slice(4, endIndex),
		body: normalized.slice(endIndex + 4).trim(),
	};
};

export const parseFrontmatter = <T extends Record<string, unknown> = Record<string, unknown>>(
	content: string,
): ParsedFrontmatter<T> => {
	const { yamlString, body } = extractFrontmatter(content);
	if (!yamlString) {
		return { frontmatter: {} as T, body };
	}
	const parsed = parse(yamlString);
	return { frontmatter: (parsed ?? {}) as T, body };
};

export const stripFrontmatter = (content: string): string => parseFrontmatter(content).body;

