/** 在卡目录内按卡号找卡文件。 */
export function findCardFile(cardsDir: string, 卡号: number): string | undefined {
	const prefix = formatCardNumber(卡号);
	return readdirSync(cardsDir).find((name) => name.startsWith(`${prefix}-`) && name.endsWith(".md"));
}

export function loadCard(cardsDir: string, 卡号: number): ParsedCard {
	const fileName = findCardFile(cardsDir, 卡号);
	if (!fileName) {
		throw new PaoCardError("CARD_NOT_FOUND", `在 ${cardsDir} 找不到卡${formatCardNumber(卡号)}`, { cardsDir, 卡号 });
	}
	return readCard(join(cardsDir, fileName));
}

/** 列出卡目录内全部卡（按卡号升序）。目录不存在视为空队列；坏卡（结构错误）跳过不炸整队。 */
export function listCards(cardsDir: string): ParsedCard[] {
	let entries: string[];
	try {
		entries = readdirSync(cardsDir);
	} catch {
		return [];
	}
	const cards: ParsedCard[] = [];
	for (const name of entries.filter((name) => /^卡0*\d+-.*\.md$/.test(name))) {
		try {
			cards.push(readCard(join(cardsDir, name)));
		} catch {
			// 坏卡跳过：队列渲染优先可用，坏卡修复属于治理动作
		}
	}
	return cards.sort((a, b) => a.卡号 - b.卡号);
}

