/** 卡正文首行的流归属标记：查流/重建清单靠它从卡反查 节点↔卡号（可从卡重建的依据）。 */
export function workflowMarker(工作流: string, 节点: string): string {
	return `<!-- pao-workflow:流=${工作流}/节点=${节点} -->`;
}

const MARKER_PATTERN = /^<!--\s*pao-workflow:流=([^/\s]+)\/节点=([^/\s]+)\s*-->/;

/** 从卡正文解析流归属标记（§11.6 按需技能挂载也走它:卡→节点→配方技能声明）。 */
export function parseWorkflowMarker(正文: string): { 流: string; 节点: string } | undefined {
	const match = MARKER_PATTERN.exec(正文.trimStart());
	return match ? { 流: match[1], 节点: match[2] } : undefined;
}

/** 时刻格式(测试可注入字符串钟;缺省走 shared/time 的唯一实现) */
function nowString(now?: () => string): string {
