}

export function manifestPath(recipe: WorkflowRecipe, options: DriverOptions): string {
	const workspaceDir = options.workspaceDir ?? dirname(options.cardsDir);
	return join(workspaceDir, `工作流实例-${recipe.名字}.md`);
}

