}

/** 状态统计不变量:未落卡 + 各卡状态计数之和 = 节点总数（每个节点恰计一次）。 */
function statsTotal(report: ReturnType<typeof buildReviewReport>): number {
	const 卡状态合计 = Object.values(report.状态统计.卡状态).reduce((sum, count) => sum + (count ?? 0), 0);
	return report.状态统计.未落卡 + 卡状态合计;
}

