			末次失败类型: 失败回执.at(-1)?.失败类型,
			人工确认: node.人工确认,
			已确认: entry?.确认,
			末次成功摘要: 末次成功?.摘要,
			产物,
			预算: node.预算,
			实耗: sumUsage([card]),
		};
