	const 状态统计: ReviewStatusStats = { 未落卡: 0, 卡状态: {} };
	for (const row of 节点) {
		if (row.卡状态 === undefined) 状态统计.未落卡 += 1;
		else 状态统计.卡状态[row.卡状态] = (状态统计.卡状态[row.卡状态] ?? 0) + 1;
	}

