/** 配方结构直接构造（parseRecipe 拒绝空节点表;无节点用例绕开解析层单测复盘统计）。 */
function emptyRecipe(): WorkflowRecipe {
	return {
		名字: "空流",
		自动执行: false,
		参数: [],
		节点: [],
		说明: "",
		文件路径: join("工作流", "空流.md"),
		占位符: [],
		拓扑序: [],
	};
}

/** 卡目录字节快照:复盘前后逐一比对,证只读。 */
function snapshotCards(cardsDir: string): Map<string, Buffer> {
	const snapshot = new Map<string, Buffer>();
	for (const name of readdirSync(cardsDir)) snapshot.set(name, readFileSync(join(cardsDir, name)));
	return snapshot;
}

