describe("状态统计（只读,基于节点行;孤儿卡不计入节点总数）", () => {
	it("混合状态+未落卡+孤儿卡:未落卡与每个实际卡状态各有明确计数,合计=节点总数,孤儿卡状态不混入;报告前后卡文件字节不变", () => {
		const cardsDir = makeDir();
		writeCard(
			cardsDir,
			1,
			"侦察",
			{ 目标: "扫仓库", 部门: "侦察", 验收: "包含: 扫", 尝试: 1, 状态: "已交付" },
			`${workflowMarker("复盘流", "侦察")}\n\n${serializeReceipt({
				卡号: 1,
				尝试号: 1,
				时间: "2026-10-03 10:40",
				结果: "成功",
				摘要: "产出了地图",
			})}`,
		);
		writeCard(
			cardsDir,
			2,
			"文档",
			{ 目标: "写文档", 部门: "文档", 验收: "包含: 文档", 尝试: 1, 状态: "失败" },
			`${workflowMarker("复盘流", "文档")}\n\n${serializeReceipt({
				卡号: 2,
				尝试号: 1,
				时间: "2026-10-03 11:00",
				结果: "失败",
				失败类型: "能力不足",
				摘要: "写崩了",
			})}`,
		);
		// 未跑节点不落卡（未落卡计数）;卡7 标记的节点不在配方里 → 孤儿卡,状态不得混入统计
		writeCard(
			cardsDir,
			7,
			"遗留",
			{ 目标: "旧活", 部门: "前端", 验收: "包含: 旧", 尝试: 1, 状态: "取消" },
			`${workflowMarker("复盘流", "已删节点")}\n\n正文`,
		);
		const recipe = parseRecipe(RECIPE_TEXT, join("工作流", "复盘流.md"));
		const before = snapshotCards(cardsDir);
		const report = buildReviewReport(recipe, cardsDir, manifest());
		const text = renderReviewReport(report);
		expect(snapshotCards(cardsDir)).toEqual(before); // 复盘只读,字节不变

		expect(report.状态统计).toEqual({ 未落卡: 1, 卡状态: { 已交付: 1, 失败: 1 } });
		// 每节点恰计一次:未落卡 + 各状态计数之和 = 节点总数
		const 合计 =
			report.状态统计.未落卡 +
			Object.values(report.状态统计.卡状态).reduce((sum, count) => sum + count, 0);
		expect(合计).toBe(report.节点.length);
		expect(合计).toBe(3);
		expect(report.状态统计.卡状态).not.toHaveProperty("取消"); // 孤儿卡状态不进统计
		expect(report.孤儿卡.map((card) => card.卡状态)).toEqual(["取消"]);
		// 序列化往返:纯数据结构,JSON 往返不变形
		expect(JSON.parse(JSON.stringify(report.状态统计))).toEqual(report.状态统计);

		expect(text).toContain("未落卡 1");
		expect(text).toContain("已交付 1");
		expect(text).toContain("失败 1");
		expect(text).toContain("孤儿卡另列不计入");
		// 现有报告信息保留
		expect(text).toContain("总账:节点 3、尝试 2、派发 2、打回 1");
		expect(text).toContain("孤儿卡（标记的节点不在配方里,配方改版遗留）:卡7→已删节点(取消)");
		expect(text).toContain("pao_落配方");
	});

	it("无节点配方:统计全零如实呈现,不虚列状态", () => {
		const report = buildReviewReport(emptyRecipe(), makeDir(), undefined);
		expect(report.节点).toEqual([]);
		expect(report.状态统计).toEqual({ 未落卡: 0, 卡状态: {} });
		const 合计 =
			report.状态统计.未落卡 +
			Object.values(report.状态统计.卡状态).reduce((sum, count) => sum + count, 0);
		expect(合计).toBe(report.节点.length);
		const text = renderReviewReport(report);
		expect(text).toContain("状态:未落卡 0（合计 0 = 节点数）");
		expect(text).toContain("总账:节点 0、尝试 0、派发 0、打回 0。");
	});

	it("全部节点未落卡（卡目录为空）:未落卡=节点数,不虚列状态", () => {
		const recipe = parseRecipe(RECIPE_TEXT, join("工作流", "复盘流.md"));
		const report = buildReviewReport(recipe, makeDir(), undefined);
		expect(report.状态统计).toEqual({ 未落卡: 3, 卡状态: {} });
		const text = renderReviewReport(report);
		expect(text).toContain("状态:未落卡 3（合计 3 = 节点数）");
	});
});

