			目标: "干活",
			部门: "前端",
			验收: "包含: 活",
			parent: "卡1",
			depends_on: ["卡1"],
		});
		const result = distillRecipe(cardsDir, "卡树流", "t");
		expect(result.边数).toBe(1); // parent 与 depends_on 指同一卡 → 去重为一条
		const recipe = parseRecipe(result.content, join("工作流", "卡树流.md"));
		const 子活 = recipe.节点.find((node) => node.名字 === "子活")!;
		expect(子活.depends_on).toEqual(["母卡"]);
	});

	it("实施记录:每卡末次成功回执的摘要＋产物进说明,失败回执不进", () => {
		const cardsDir = makeDir();
		const body = [
			serializeReceipt({
