/**
 * 注册工作流工具与 /pao flow 子命令（pi 扩展入口）。
 * 模型面四工具：启流（校验参数＋写实例清单＋落首批卡）、推流（断点续跑 tick）、
 * 查流（只读聚合：当前节点/卡号/pao status）、确认流（人工门点头后续跑）。
 */
export function registerWorkflowTools(pi: ExtensionAPI, options?: WorkflowToolsOptions): void {
	// §11.6 跑后复盘·终态提醒（与 §20 pao-fanout-done 同机制）:实例到终态（全部交付/有节点失败）
	// → 下一轮 before_agent_start 消费式注入提醒;会话级内存态（R25 重启归零）,同一流一次终态只提醒一次。
	const 复盘待注入: string[] = [];
	const 已提醒终态 = new Set<string>();
	const queueReview = (report: DriveReport): void => {
		const 终态 = report.状态 === "已完成" || report.节点.some((node) => node.状态 === "失败");
		if (!终态 || 已提醒终态.has(report.工作流)) return;
		已提醒终态.add(report.工作流);
		复盘待注入.push(
			`工作流「${report.工作流}」已到终态（${report.状态 === "已完成" ? "全部交付" : "有节点失败"}）——请调 pao_复盘流 出机械报告,基于报告给改进意见,用户拍板后用 pao_落配方 回写配方。`,
		);
	};
	// 命令/工具两面共用的注册态：复盘同一队列＋toast 开关同源（核心收口 2026-10-03）
	const common: WorkflowCommon = { queueReview, paoHome: options?.resolvePaoHome?.() };
	pi.on("before_agent_start", (event) => {
		if (复盘待注入.length === 0) return;
		const body = 复盘待注入.splice(0).join("\n\n");
		event.systemPromptOptions.sections[WORKFLOW_REVIEW_SECTION] =
			`[pao 工作流复盘提醒] 以下工作流已跑完,等复盘（运行态通知,重启归零;卡与回执是真相,R25）:\n${body}`;
	});

	const baseParams = {
		名字: Type.String({ description: "工作流配方名（<PAO_HOME>/工作流/<名字>.md）" }),
		卡目录: Type.Optional(Type.String({ description: CARDS_DIR_DESC })),
	};

	pi.registerTool({
		name: "pao_启流",
		label: "启动工作流",
		description:
			"一键启动工作流：按配方名从 <PAO_HOME>/工作流/<名字>.md 加载并校验（有向无环、参数占位符全有值才放行），写实例清单 工作流实例-<名字>.md，落首批卡（depends_on 全完成的节点）。同一流已有实例清单时拒绝重复启动。配方标 自动执行: true 时首批卡直接进自动链（派发→回执→越界核查→机械验收→交卷→解锁下游）；缺省只落卡。",
		parameters: Type.Object({
			...baseParams,
			参数: Type.Optional(
				Type.Record(Type.String(), Type.String(), { description: "配方参数占位符的取值，键值对" }),
			),
		}),
		execute: async (_toolCallId, params: ToolParams, signal) =>
			toolResult(async () =>
				startWorkflowCore(loadRecipeFor(params, options), params.参数 ?? {}, buildAutoOptions(params, options, signal), common),
			),
	});

	pi.registerTool({
		name: "pao_推流",
		label: "推进工作流",
		description:
			"推进工作流一个驱动循环：从卡现读各节点状态，把 depends_on 全部已交付（人工门已确认）的未跑节点落卡。挂起补齐后、回执交付后调用它续跑；失败即停不硬闯。配方标 自动执行: true 时落卡后自动走全链（派发→回执→越界核查→机械验收→交卷→解锁下游）直到停因（人工门/失败/留 owner）；缺省只落卡。",
		parameters: Type.Object(baseParams),
		execute: async (_toolCallId, params: ToolParams, signal) =>
			toolResult(async () =>
				tickWorkflowCore(loadRecipeFor(params, options), buildAutoOptions(params, options, signal), common),
			),
	});

	pi.registerTool({
		name: "pao_查流",
		label: "查工作流",
		description:
			"查工作流进度（只读）：当前跑到哪个节点、各节点卡号与卡状态、人工门与挂起原因。真相在卡上，实例清单只提供映射；清单缺失时自动从卡正文标记重建视图。",
		parameters: Type.Object(baseParams),
		execute: async (_toolCallId, params: ToolParams) =>
			toolResult(async () => queryWorkflowCore(loadRecipeFor(params, options), buildDriverOptions(params, options))),
	});

	pi.registerTool({
		name: "pao_确认流",
		label: "确认工作流节点",
		description:
			"人工门点头：对标记人工确认且卡已交付的节点记录确认并立即续跑（放行下游）。未交付、未标人工门的节点会被拒绝。配方标 自动执行: true 时点头后续跑走自动链。",
		parameters: Type.Object({
			...baseParams,
			节点: Type.String({ description: "要确认的节点名" }),
		}),
		execute: async (_toolCallId, params: ToolParams, signal) =>
			toolResult(async () =>
				confirmWorkflowCore(
					loadRecipeFor(params, options),
					params.节点!,
					buildAutoOptions(params, options, signal),
					common,
				),
			),
	});

	// 生成路两工具（2026-10-03 拍板「走完一次存配方」）:蒸馏出草稿、校验后落盘。
	// 从零起草路（对话里主控手写配方）不经 pao_存流,但落盘同样过 pao_落配方 这一个机械校验闸。
	pi.registerTool({
		name: "pao_存流",
